<article class="blog-card"><a href="/blogs/{{ $blog->slug }}" class="blog-card-cover" tabindex="-1" aria-hidden="true"><img src="/{{ $blog->image ?: 'assets/brand/kitchen-tasting.webp' }}" alt="" loading="lazy" width="640" height="420"></a><div class="blog-card-copy"><span class="eyebrow">{{ $blog->category }}</span><h3><a href="/blogs/{{ $blog->slug }}">{{ $blog->title }}</a></h3><p>{{ $blog->excerpt }}</p><div class="blog-byline"><span>{{ $blog->author }}</span><span>{{ max(1,(int)ceil(str_word_count($blog->body)/200)) }} min read</span></div></div></article>
